// Build src/assets/js/airguide-tables.js from the AirGuide catalog transcriptions
// in calc-cases/sources. check-airguide.mjs (npm test) holds the result to them.
//
//   node tools/extract/build-airguide.mjs
import fs from 'node:fs';
import { parseAirguide } from './airguide.mjs';

const cat = f => parseAirguide(`calc-cases/sources/${f}`);
fs.writeFileSync('src/assets/js/airguide-tables.js', `// GENERATED by tools/extract/build-airguide.mjs from calc-cases/sources.
// Do not edit: fix the transcription (or the generator) and rebuild.
//
// AirGuide performance data, as { vel: [fpm], header: { name: [values] },
// sizes: [{ area ft², labels, ak, rows: { CFM, NC, throws... } }] }.
// "—" is the catalog's dash (NC below its range); null an empty cell.
export const AG_CB = ${JSON.stringify(cat('airguide-cb.txt'))};
export const AG_RA = ${JSON.stringify(cat('airguide-ra.txt'))};
export const AG_V = ${JSON.stringify(cat('airguide-v.txt'))};
`);
console.log('written');
